<?php require __DIR__.'/../includes/bootstrap.php'; if(!empty($_SESSION['user_id'])){header('Location: index.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??''))$err='Session expired.';else{$q=$pdo->prepare('SELECT id,password_hash,role,status FROM users WHERE email=?');$q->execute([trim($_POST['email']??'')]);$u=$q->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])&&$u['status']==='active'&&$u['role']!=='player'){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));header('Location: index.php');exit;} $err='Invalid admin credentials.';}} if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32)); ?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><script src="https://cdn.tailwindcss.com"></script><title>ArenaX Admin Login</title></head><body class="bg-slate-950 text-white min-h-screen grid place-items-center"><form method="post" class="bg-slate-900 border border-slate-800 p-7 rounded-2xl w-[min(92vw,400px)] space-y-4"><h1 class="text-2xl font-bold">ArenaX Admin</h1><p class="text-slate-400 text-sm">Secure management console</p><?php if($err):?><p class="text-red-400"><?=h($err)?></p><?php endif?><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input required type="email" name="email" placeholder="Admin email" class="w-full p-3 rounded-lg bg-slate-800"><input required type="password" name="password" placeholder="Password" class="w-full p-3 rounded-lg bg-slate-800"><button class="w-full bg-violet-600 p-3 rounded-lg font-semibold">Sign in</button></form></body></html>
